      qq_markdown: "Markdown Replies",
      qq_markdown_help: "Enable QQ markdown reply mode if your bot account supports it.",
      imessage_include_attachments: "Include Attachments",
      imessage_include_attachments_help: "Attach metadata for images and files when available.",
      slack_setup: "Create a Slack app → enable Socket Mode → copy App Token & Bot Token",
      slack_setup_details: '<ol><li>Go to <a href="https://api.slack.com/apps" target="_blank">api.slack.com/apps</a> and click <b>Create New App</b> → <b>From scratch</b></li><li>Under <b>Socket Mode</b> (left menu), toggle it <b>On</b> and generate an <b>App-Level Token</b> with <code>connections:write</code> scope — this is your <b>App Token</b> (starts with <code>xapp-</code>)</li><li>Under <b>App Home</b>, check <b>Allow users to send Slash commands and messages from the messages tab</b></li><li>Under <b>OAuth &amp; Permissions</b>, add these <b>Bot Token Scopes</b>:<br><code>app_mentions:read</code>, <code>chat:write</code>, <code>channels:history</code>, <code>groups:history</code>, <code>im:history</code>, <code>im:read</code>, <code>files:read</code>, <code>files:write</code>, <code>users:read</code></li><li>Under <b>Event Subscriptions</b>, toggle <b>On</b>, then under <b>Subscribe to bot events</b> add:<br><code>app_mention</code>, <code>message.im</code>, <code>member_joined_channel</code></li><li>Click <b>Install to Workspace</b> (or <b>Reinstall</b> if updating) and copy the <b>Bot User OAuth Token</b> (starts with <code>xoxb-</code>)</li><li>Paste both tokens below and click <b>Start</b></li></ol>',
      telegram_setup: "Create a bot via {'@'}BotFather → paste the token below",
      telegram_setup_details: `<ol><li>Open Telegram and search for <a href="https://t.me/BotFather" target="_blank">{'@'}BotFather</a></li><li>Send <code>/newbot</code> and follow the prompts to choose a name and username</li><li>BotFather will give you a <b>Bot Token</b> — copy it</li><li>Paste the token below and click <b>Start</b></li><li><i>Optional:</i> Add usernames or user IDs in <b>Allowed Users</b> to restrict access</li></ol>`,
      discord_setup: "Create an app in Developer Portal → add a Bot → copy token",
      discord_setup_details: '<ol><li>Go to <a href="https://discord.com/developers/applications" target="_blank">Discord Developer Portal</a>. If prompted, select <b>Build a Bot</b> and click <b>Continue to Portal</b></li><li>Click <b>New Application</b>, give it a name, and create it</li><li>Go to <b>Bot</b> tab → click <b>Reset Token</b> to get the bot token</li><li>Under <b>Privileged Gateway Intents</b>, enable <b>Message Content Intent</b></li><li>Go to <b>OAuth2 → URL Generator</b>, select scopes <code>bot</code>, and permissions: <code>Send Messages</code>, <code>Read Message History</code>, <code>Attach Files</code></li><li>Open the generated URL to invite the bot to your server</li><li>Paste the bot token below and click <b>Start</b></li></ol>',
      wechat_setup: "Click Start below, then scan the QR code with WeChat to connect",
      feishu_setup: "Create a Feishu app -> batch import permissions -> enable Bot and events -> publish before starting",
      feishu_setup_details: '<ol><li>Go to <a href="https://open.feishu.cn/app" target="_blank">Feishu Open Platform</a>, create an app, then copy the <b>App ID</b> and <b>App Secret</b> from <b>Credentials &amp; Basic Info</b></li><li>Open <b>Permissions</b>, click <b>Batch import</b>, and import the required JSON</li><li>Open <b>Event Subscriptions</b>, choose <b>long connection / WebSocket</b>, and add <code>im.message.receive_v1</code>. If you use Webhook mode, also fill in <b>Verification Token</b> and <b>Encrypt Key</b> below</li><li>Open <b>Version Management &amp; Release</b> and publish the current version</li><li>Return to Pantheon UI and fill in the credentials below. If you use Webhook mode, also provide <b>Host</b>, <b>Port</b>, and <b>Webhook Path</b>, then click <b>Start</b></li><li><i>Note:</i> for international Lark tenants, use the matching developer portal domain and configure <code>domain: "lark"</code> in the backend</li></ol>',
      feishu_batch_import_copy: "Copy JSON",
